<script setup lang="ts">
import {computed,ref} from 'vue';
import {state,change,ui} from '../state';
import {locationOptions,planningLocations,HOMEWORK_LOCATION} from '../domain/planning-locations';
import {editCurriculum,type CurriculumDraft} from '../domain/curriculum-editing';
import type {OasRequirement} from '../domain/models';
const query=ref(''),stage=ref(''),theme=ref(''),location=ref(''),selected=ref(''),linkSearch=ref(''),newTheme=ref(''),newLocation=ref('');
const duplicateSearch=ref('');
const duplicateChoices=computed(()=>requirements.value.filter(r=>r.id!==selected.value&&[r.text,r.id].join(' ').toLowerCase().includes(duplicateSearch.value.toLowerCase())));
const draft=ref<CurriculumDraft|null>(null),baseline=ref('');
const requirements=computed(()=>state.value!.requirements);
const themes=computed(()=>[...new Set(requirements.value.flatMap(r=>(r.theme_tags as string[]|undefined)??r.tags).concat(draft.value?.themes??[]))].sort());
const locations=computed(()=>[...new Set([HOMEWORK_LOCATION,...requirements.value.flatMap(locationOptions),...(draft.value?.alternatives??[]),draft.value?.preferred??''])].filter(Boolean).sort());
const rows=computed(()=>requirements.value.filter(r=>(!stage.value||r.stage===Number(stage.value))&&(!theme.value||((r.theme_tags as string[]|undefined)??r.tags).includes(theme.value))&&(!location.value||locationOptions(r).includes(location.value))&&(!query.value||[r.text,r.id,r.stream,...r.tags].join(' ').toLowerCase().includes(query.value.toLowerCase()))));
const current=computed(()=>requirements.value.find(r=>r.id===selected.value));
const links=computed(()=>requirements.value.filter(r=>r.id!==selected.value&&(!linkSearch.value||[r.text,r.id,'Stage '+r.stage].join(' ').toLowerCase().includes(linkSearch.value.toLowerCase()))));
function open(r:OasRequirement){selected.value=r.id;baseline.value=JSON.stringify(requirements.value);const loc=planningLocations(r);draft.value={stage:r.stage,recommendationsArePrerequisites:r.recommended_as_prerequisites!==false,duplicateIds:[...new Set([...(r.duplicates??[]),...(r.duplicate_of?[r.duplicate_of]:[])])],themes:[...((r.theme_tags as string[]|undefined)??r.tags)],preferred:loc.preferred??'',alternatives:[...(loc.alternatives??[])],prerequisites:[...r.prerequisites],suggested:(r.suggested_links??[]).map(l=>l.id)};linkSearch.value='';newTheme.value='';newLocation.value='';ui.requirementId='';}
function save(){if(baseline.value!==JSON.stringify(requirements.value)){ui.error='Curriculum changed. Reopen the statement before saving.';return;}if(change('Before curriculum structure edit',s=>{s.requirements=editCurriculum(s.requirements,selected.value,draft.value!);})){baseline.value=JSON.stringify(requirements.value);}}
function addTheme(){const t=newTheme.value.trim();if(t&&!draft.value!.themes.includes(t))draft.value!.themes.push(t);newTheme.value='';}
function addLocation(){const l=newLocation.value.trim();if(l&&!draft.value!.alternatives.includes(l))draft.value!.alternatives.push(l);newLocation.value='';}
</script>
<template><section><p>Edit the structure the scheduler uses: stages, themes, locations and prerequisite links. Scout evidence stays unchanged. Saved edits create a recovery checkpoint.</p><div class="toolbar filter-panel"><label>Find a statement<input v-model="query" type="search" placeholder="Statement, ID or stream"></label><label>Stage<select v-model="stage"><option value="">All stages</option><option v-for="n in [1,2,3]" :key="n">{{n}}</option></select></label><label>Theme<select v-model="theme"><option value="">All themes</option><option v-for="t in themes" :key="t">{{t}}</option></select></label><label>Location<select v-model="location"><option value="">All locations</option><option v-for="l in locations" :key="l">{{l}}</option></select></label></div>
<div class="curriculum-layout"><div><p>{{rows.length}} statements · select one to edit its structure</p><div class="table-scroll"><table class="coverage-table"><thead><tr><th>OAS statement</th><th>Stage / stream</th><th>Themes</th><th>Locations</th><th>Links</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" :class="{selected:selected===r.id}"><td><button class="text-link" @click="open(r)">{{r.text}}</button><small>{{r.id}}</small></td><td>Stage {{r.stage}}<small>{{r.stream}}</small></td><td><span v-for="t in ((r.theme_tags as string[]|undefined)??r.tags)" :key="t" class="curriculum-chip">{{t}}</span></td><td>{{planningLocations(r).preferred||'Flexible / anywhere'}}<small v-if="planningLocations(r).alternatives?.length">Also: {{planningLocations(r).alternatives!.join(', ')}}</small></td><td>→ {{r.prerequisites.length}} required<small>⇢ {{r.suggested_links?.length??0}} recommended</small></td></tr><tr v-if="!rows.length"><td colspan="5">No matching statements.</td></tr></tbody></table></div></div>
<form v-if="draft&&current" class="curriculum-form panel" @submit.prevent="save"><div class="curriculum-editor-heading"><div><p class="eyebrow">Curriculum structure</p><h2>{{current.text}}</h2><small>{{current.id}} · {{current.stream}}</small></div><button type="button" aria-label="Close curriculum editor" @click="draft=null;selected=''">×</button></div><label>Stage<select v-model.number="draft.stage"><option v-for="n in [1,2,3]" :key="n" :value="n">Stage {{n}}</option></select></label><p class="muted">Readiness follows statement links, not completion of whole earlier stages. Each Scout is assigned one stage activity per week.</p>
<fieldset><legend>Themes used for scheduling</legend><div class="curriculum-options"><label v-for="t in themes" :key="t" class="check"><input v-model="draft.themes" type="checkbox" :value="t">{{t}}</label></div><div class="toolbar"><label>New theme<input v-model="newTheme" @keydown.enter.prevent="addTheme"></label><button type="button" @click="addTheme">Add theme</button></div></fieldset>
<fieldset><legend>Locations</legend><label>Preferred location<select v-model="draft.preferred"><option value="">Flexible / anywhere</option><option v-for="l in locations" :key="l">{{l}}</option></select></label><p>Alternative locations are also allowed when scheduling this statement.</p><div class="curriculum-options"><label v-for="l in locations.filter(l=>l!==draft!.preferred)" :key="l" class="check"><input v-model="draft.alternatives" type="checkbox" :value="l">{{l}}</label></div><div class="toolbar"><label>New location<input v-model="newLocation" @keydown.enter.prevent="addLocation"></label><button type="button" @click="addLocation">Add location</button></div></fieldset>
<fieldset><legend>Duplicate statements</legend><p>Equivalent statements share a scheduling group. Only one is selected per night; later weeks can repeat it when more sessions are needed. Scout evidence stays separate.</p><label>Find duplicates<input v-model="duplicateSearch" type="search" placeholder="Search equivalent statements"></label><div class="selected-links"><p v-for="id in draft.duplicateIds" :key="id">{{requirements.find(r=>r.id===id)?.text}}<button type="button" @click="draft.duplicateIds=draft.duplicateIds!.filter(x=>x!==id)">Remove duplicate</button></p></div><div class="curriculum-link-options"><label v-for="r in duplicateChoices" :key="r.id" class="check"><input v-model="draft.duplicateIds" type="checkbox" :value="r.id"><span>{{r.text}}<small>Stage {{r.stage}} · {{r.stream}}</small></span></label></div></fieldset>
<fieldset><legend>Statement links</legend><label class="check"><input v-model="draft.recommendationsArePrerequisites" type="checkbox">Treat recommended links as prerequisites</label><p>→ Mandatory prerequisite · ⇢ Recommended link. Recommended links are prerequisites by default. Circular readiness links cannot be saved.</p><label>Find linked statements<input v-model="linkSearch" type="search" placeholder="Search statement, ID or stage"></label><div class="selected-links"><p v-for="id in [...new Set([...draft.prerequisites,...draft.suggested])]" :key="id">{{requirements.find(r=>r.id===id)?.text}}<button type="button" @click="draft.prerequisites=draft.prerequisites.filter(x=>x!==id);draft.suggested=draft.suggested.filter(x=>x!==id)">Remove link</button></p></div><div class="curriculum-link-options"><div v-for="r in links" :key="r.id"><span>{{r.text}}<small>Stage {{r.stage}} · {{r.stream}} · {{r.id}}</small></span><label class="check"><input v-model="draft.prerequisites" type="checkbox" :value="r.id">→ Required</label><label class="check"><input v-model="draft.suggested" type="checkbox" :value="r.id">⇢ Recommended</label></div></div></fieldset><div class="curriculum-save"><button class="primary">Save structure</button><button type="button" @click="open(current)">Discard edits</button></div></form><aside v-else class="panel curriculum-empty"><h2>Shape the curriculum</h2><p>Choose a statement from the table to edit its scheduling rules and connections.</p></aside></div></section></template>
